"""Check all elements in iterable like list are identical."""
def all_elements_are_identical(iterator: Any) -> object {
    iterator = iter(iterator);
    try {
        first = next(iterator);
    } except StopIteration {
        return True;
    }
    return all((first == rest) for rest in iterator);
}

